/** Kenyan mobile helpers — same rules as the website customer tab. */

export function kenyanMobileDigits(raw: string): string {
  return raw.trim().replace(/\D/g, '');
}

export function looksLikeKenyanMobile(raw: string): boolean {
  const digits = kenyanMobileDigits(raw);
  return /^2547\d{8}$/.test(digits) || /^07\d{8}$/.test(digits) || /^7\d{8}$/.test(digits);
}

export function toKenyanLocal07(raw: string): string | null {
  const digits = kenyanMobileDigits(raw);
  if (/^2547\d{8}$/.test(digits)) return `0${digits.slice(3)}`;
  if (/^07\d{8}$/.test(digits)) return digits;
  if (/^7\d{8}$/.test(digits)) return `0${digits}`;
  return null;
}

export function formatPhoneDisplay(raw: string): string {
  const local = toKenyanLocal07(raw) || kenyanMobileDigits(raw);
  if (local.length === 10 && local.startsWith('07')) {
    return `${local.slice(0, 4)} ${local.slice(4, 7)} ${local.slice(7)}`;
  }
  return raw.trim();
}

export type KenyanNetwork = 'SAFARICOM' | 'AIRTEL' | 'TELKOM' | 'EQUITEL' | 'JTL';

export function detectKenyanNetwork(raw: string): KenyanNetwork | null {
  const local = toKenyanLocal07(raw);
  if (!local) return null;
  const prefix = Number.parseInt(local.slice(1, 4), 10);
  if (!Number.isFinite(prefix)) return null;
  if (prefix === 747) return 'JTL';
  if (prefix >= 763 && prefix <= 765) return 'EQUITEL';
  if (prefix >= 770 && prefix <= 779) return 'TELKOM';
  if (
    (prefix >= 100 && prefix <= 102) ||
    (prefix >= 730 && prefix <= 739) ||
    (prefix >= 750 && prefix <= 756) ||
    prefix === 762 ||
    (prefix >= 780 && prefix <= 789)
  ) {
    return 'AIRTEL';
  }
  if (
    (prefix >= 110 && prefix <= 115) ||
    (prefix >= 700 && prefix <= 729) ||
    (prefix >= 740 && prefix <= 746) ||
    prefix === 748 ||
    (prefix >= 757 && prefix <= 759) ||
    (prefix >= 768 && prefix <= 769) ||
    (prefix >= 790 && prefix <= 799)
  ) {
    return 'SAFARICOM';
  }
  return null;
}

export const KENYAN_NETWORKS: { id: KenyanNetwork; label: string; short: string }[] = [
  { id: 'SAFARICOM', label: 'Safaricom', short: 'Saf' },
  { id: 'AIRTEL', label: 'Airtel', short: 'Air' },
  { id: 'TELKOM', label: 'Telkom', short: 'Tel' },
  { id: 'EQUITEL', label: 'Equitel', short: 'Equ' },
  { id: 'JTL', label: 'JTL', short: 'JTL' },
];

export function sameNumber(a: string, b: string): boolean {
  return (toKenyanLocal07(a) || kenyanMobileDigits(a)) === (toKenyanLocal07(b) || kenyanMobileDigits(b));
}
